    "notas": [
      "Sacado del timeline de Hudl (el etiquetado de Wyscout del partido), no mirando imagen a imagen: salen TODOS los robos del partido.",
      "Cuenta como robo la interceptación, el duelo defensivo que acaba con el balón nuestro y la recuperación con el rival presionado o tras nuestra pérdida. No cuentan las del portero, las que vienen de un despeje, un rechace o un balón parado del rival, ni las faltas pitadas.",
      "El segundo es el del vídeo táctico del club, atado al de Hudl por tramos medidos jugada a jugada.",
      "Vídeo táctico (dron): en las DOS partes el Castilla defiende la portería de abajo (la más cercana a la cámara) y ataca la de arriba; en el descanso el dron cambió de fondo. Castilla de blanco (portero 13 Navarro de negro), Algeciras rojiblanco a rayas con pantalón azul (portero de verde).",
      "Cortes de la táctica: hacia el segundo 1893 el dron baja a cambiar batería y vuelve a grabar en el 1905 (no está lo de Hudl ~1891-1943, 31'-32', incluida la falta de Fati Joao del 32'); el descanso va grabado (del ~2742 al ~2900, con el dron fuera del campo); hacia el 4448 hay otro cambio de batería (no está lo de Hudl ~4298-4360, 72'-73').",
      "Desfase táctica − Hudl por tramos (tramos.json): +2 s hasta el ~31', −35 s hasta el descanso, +150 s en la 2ª parte hasta el ~72' y +90 s hasta el final. Medido con el saque inicial, el córner del 7', el 0-1, el córner del 31', los córners del 36'-38', el córner del 48', el 0-2, el tiro del 67' y los córners del 81' y 89'.",
      "Goles vistos en la táctica: 0-1 (racimo en el área de abajo hacia el segundo 1200-1204 y celebración del Algeciras después) y 0-2 (llegada al área de abajo hacia el 3979-3993 y celebración en la esquina de abajo a la izquierda desde el ~4011)."
    ],
